import "server-only";

import { auth } from "@clerk/nextjs/server";

// The single typed HTTP transport seam for the web client (ADR-0022). Every
// server-side read and write goes through `apiGet`/`apiSend`, which own base-URL
// prefixing, Clerk JWT attach, `fetch`, `cache: "no-store"`, and the envelope cast.
// The eleven `lib/*.ts` data-access modules keep only their paths, methods, and
// request/response types and delegate the transport here. The seam returns the raw
// `Envelope`; the `.success`/`.data`/`.error` unwrap stays at the ~30 call sites, the
// front-end twin of the backend's `StructuredLLM` port returning raw text (ADR-0006).
//
// `import "server-only"` makes any accidental import from a Client Component fail at
// build time, so the JWT-attach path can never leak into the browser bundle.
const API_URL = process.env.API_URL ?? "http://localhost:8000";

// A 204 No Content success carries no response body, so `response.json()` must be skipped.
const HTTP_NO_CONTENT = 204;

// Pagination metadata a paginated endpoint attaches alongside `data`: the full record
// `total` across every page, and the `limit`/`offset` window this page was read with.
export interface PaginationMeta {
  total: number;
  limit: number;
  offset: number;
}

// The standard wire envelope every backend endpoint returns. Declared once here so
// the domain modules stop re-declaring it and `apiGet`/`apiSend` can name their
// return type; callers keep inferring it. `meta` rides only on paginated responses.
export interface Envelope<T> {
  success: boolean;
  data: T | null;
  error: string | null;
  meta?: PaginationMeta;
}

async function authHeaders(): Promise<Record<string, string>> {
  const { getToken } = await auth();
  const token = await getToken();
  return { Authorization: `Bearer ${token}` };
}

// Read a backend endpoint. Attaches the Clerk JWT, prefixes the API base URL, sets
// `cache: "no-store"`, and returns the raw envelope for the caller to unwrap.
export async function apiGet<T>(path: string): Promise<Envelope<T>> {
  const response = await fetch(`${API_URL}${path}`, {
    headers: await authHeaders(),
    cache: "no-store",
  });
  return (await response.json()) as Envelope<T>;
}

// Write to a backend endpoint (POST, PUT, PATCH, or DELETE). `Content-Type:
// application/json` and the JSON-stringified body are attached only when a `body` is
// passed; a bodyless call (the `substitute` POST, a `DELETE`) sends neither, byte-for-byte
// as before (ADR-0022). PATCH carries the admin partial-edit payload (issue #502).
export async function apiSend<T>(
  path: string,
  method: "POST" | "PUT" | "PATCH" | "DELETE",
  body?: unknown,
): Promise<Envelope<T>> {
  const headers = await authHeaders();
  const init: RequestInit =
    body === undefined
      ? { method, headers, cache: "no-store" }
      : {
          method,
          headers: { ...headers, "Content-Type": "application/json" },
          body: JSON.stringify(body),
          cache: "no-store",
        };
  const response = await fetch(`${API_URL}${path}`, init);
  // A 204 No Content success (e.g. removing a relationship link, issue #505) has no body,
  // so `response.json()` would throw — synthesize the success envelope instead. Every error
  // response still carries the JSON envelope (see the API's exception handlers), so only the
  // bodyless 204 needs this branch.
  if (response.status === HTTP_NO_CONTENT) {
    return { success: true, data: null, error: null };
  }
  return (await response.json()) as Envelope<T>;
}

// Upload a file to a backend endpoint as `multipart/form-data` — the one non-JSON write in the
// otherwise-JSON seam, added for the curator Exercise Image upload (issue #504). The file is
// sent under the `file` field the backend's `UploadFile` reads. Only the Clerk JWT is attached:
// the `Content-Type` (with its multipart boundary) is set by `fetch` from the `FormData` body,
// so it must NOT be set by hand. Returns the raw envelope like the JSON writers.
export async function apiUpload<T>(path: string, file: File): Promise<Envelope<T>> {
  const form = new FormData();
  form.append("file", file);
  const response = await fetch(`${API_URL}${path}`, {
    method: "POST",
    headers: await authHeaders(),
    body: form,
    cache: "no-store",
  });
  return (await response.json()) as Envelope<T>;
}

// Fetch raw bytes from a backend endpoint (not the JSON envelope) with the Clerk JWT attached —
// used by the Exercise Image render proxy so the browser's same-origin `<img>` can reach the
// JWT-guarded `GET /api/exercises/{id}/image`. Returns the raw `Response` so the caller can
// stream the body and forward the upstream status/content-type.
export async function apiGetRaw(path: string): Promise<Response> {
  return fetch(`${API_URL}${path}`, {
    headers: await authHeaders(),
    cache: "no-store",
  });
}
import Link from "next/link";
import { notFound } from "next/navigation";
import { CheckCircle2 } from "lucide-react";

import { fetchProtocol } from "@/lib/protocols";
import type { ProtocolProgress, ProtocolSession } from "@/lib/protocols-types";
import type { ExercisePrescription } from "@/lib/sessions-types";
import { appendFrom } from "@/lib/back-target";
import { PageHeader } from "@/components/pulse/page-header";
import { SectionHeader } from "@/components/pulse/section-header";
import { SegmentedBar } from "@/components/pulse/segmented-bar";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";

// Displays a user-owned multi-week Protocol: its self-paced next Session and the
// full week-by-week schedule. Upcoming Sessions show the recommended load already
// progressed from the user's Logged Sets (ADR-0004); the backend returns 404
// (→ notFound) for anyone who does not own the Protocol.
export default async function ProtocolPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  const protocolId = Number(id);
  if (!Number.isInteger(protocolId)) notFound();

  const envelope = await fetchProtocol(protocolId);
  if (!envelope.success || !envelope.data) {
    notFound();
  }

  const protocol = envelope.data;
  const total = protocol.sessions.length;
  const done = protocol.completed_count;
  const progress = total > 0 ? done / total : 0;

  return (
    <section className="flex flex-col gap-7">
      <PageHeader
        overline="PULSE // PROTOCOL"
        title={<span>{protocol.label}</span>}
        action={
          <div className="flex items-center gap-3">
            <Badge variant="cyan">{protocol.weeks}W</Badge>
            <Link
              href={`/protocols/${protocol.id}/edit`}
              className="label-mono text-[10px] text-text-muted transition-colors hover:text-cyan"
            >
              EDIT
            </Link>
          </div>
        }
      />

      {/* Protocol overview + completion. */}
      <Card className="flex flex-col gap-4 p-5">
        <div className="flex items-center justify-between">
          <span className="label-mono text-[11px] capitalize text-cyan">
            {protocol.objective}
          </span>
          <span className="label-mono text-[10px] text-text-muted">
            {done}/{total} DONE
          </span>
        </div>
        <SegmentedBar value={progress} segments={Math.min(total, 14) || 1} />
        <NextUp protocol={protocol} protocolId={protocolId} />
      </Card>

      <div className="flex flex-col gap-4">
        <SectionHeader meta={`${total} SESSIONS`}>SCHEDULE</SectionHeader>
        <ol className="flex list-none flex-col gap-3 p-0">
          {protocol.sessions.map((session, index) => (
            <li key={session.session_id}>
              <SessionCard
                session={session}
                index={index + 1}
                isNext={session.session_id === protocol.next_session?.session_id}
                protocolId={protocolId}
              />
            </li>
          ))}
        </ol>
      </div>
    </section>
  );
}

function NextUp({
  protocol,
  protocolId,
}: {
  protocol: ProtocolProgress;
  protocolId: number;
}) {
  if (protocol.next_session === null) {
    return (
      <div className="flex items-center gap-2.5 rounded-sm border border-cyan/40 bg-cyan-dim px-3.5 py-3">
        <CheckCircle2 className="h-4 w-4 shrink-0 text-cyan" aria-hidden />
        <span className="font-mono text-[13px] text-cyan">
          Protocol complete — every session has been logged.
        </span>
      </div>
    );
  }
  const next = protocol.next_session;
  return (
    <div className="flex flex-col gap-3">
      <span className="label-mono text-[10px] text-text-muted">NEXT UP</span>
      <SessionCard
        session={next}
        index={next.day}
        isNext
        protocolId={protocolId}
      />
    </div>
  );
}

function SessionCard({
  session,
  index,
  isNext,
  protocolId,
}: {
  session: ProtocolSession;
  index: number;
  isNext: boolean;
  protocolId: number;
}) {
  return (
    <div
      className={`flex flex-col gap-3 rounded-md border p-4 ${
        isNext
          ? "border-cyan/60 bg-elevated"
          : "border-border bg-surface"
      }`}
    >
      <div className="flex items-center gap-3">
        <span
          className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-sm font-mono text-[13px] font-bold ${
            isNext ? "bg-cyan text-on-accent" : "bg-base text-cyan"
          }`}
        >
          {String(index).padStart(2, "0")}
        </span>
        <div className="flex flex-1 flex-col gap-0.5">
          <span className="font-display text-[15px] font-semibold text-text-primary">
            Week {session.week}, Day {session.day}
            {session.title ? ` — ${session.title}` : ""}
          </span>
          <span className="label-mono text-[9px] text-text-muted">
            {session.prescriptions.length} EXERCISES
          </span>
        </div>
        {isNext ? <Badge variant="cyan">NEXT</Badge> : null}
      </div>

      <ul className="flex flex-col gap-1.5 border-t border-border pt-3">
        {session.prescriptions.map((prescription) => (
          <li key={prescription.position}>
            <PrescriptionRow
              prescription={prescription}
              protocolId={protocolId}
            />
          </li>
        ))}
      </ul>
    </div>
  );
}

function PrescriptionRow({
  prescription,
  protocolId,
}: {
  prescription: ExercisePrescription;
  protocolId: number;
}) {
  return (
    <div className="flex items-center justify-between gap-3">
      <Link
        href={appendFrom(
          `/exercises/${prescription.exercise_id}`,
          `/protocols/${protocolId}`,
        )}
        className="truncate font-sans text-[13px] text-text-secondary transition-colors hover:text-cyan"
      >
        {prescription.exercise_name}
      </Link>
      <span className="shrink-0 font-mono text-[12px] text-text-muted">
        {prescription.sets} × {prescription.reps}
        {prescription.recommended_load
          ? ` @ ${prescription.recommended_load.text}`
          : ""}
      </span>
    </div>
  );
}
import { ProfileForm } from "@/components/ProfileForm";
import { fetchProfile } from "@/lib/profile";
import { PageHeader } from "@/components/pulse/page-header";
import { BackLink } from "@/components/pulse/back-link";
import { Alert } from "@/components/pulse/alert";

// Later edits to the Fitness Profile. The Profile is a mutable snapshot of
// "now", so editing simply overwrites the current values.
export default async function EditProfilePage() {
  const envelope = await fetchProfile();

  if (!envelope.success || !envelope.data) {
    return (
      <section className="flex flex-col gap-6">
        <PageHeader overline="PULSE // OPERATOR" title="Edit profile" />
        <Alert tone="error">
          Could not load your profile: {envelope.error ?? "unknown error"}
        </Alert>
      </section>
    );
  }

  return (
    <section className="flex flex-col gap-6">
      <PageHeader overline="PULSE // OPERATOR" title="Edit profile" />
      <ProfileForm profile={envelope.data} submitLabel="Save changes" />
      <BackLink href="/dashboard">Back to dashboard</BackLink>
    </section>
  );
}

function sensitiveConstraints(form: FormData): string[] {
  return form
    .getAll("sensitive_constraints")
    .filter((value): value is string => typeof value === "string")
    .filter((value) => VALID_SENSITIVE.has(value));
}

function toProfileInput(form: FormData): ProfileInput {
  return {
    display_name: text(form, "display_name"),
    gender: gender(form),
    age: number(form, "age"),
    height_cm: number(form, "height_cm"),
    weight_kg: number(form, "weight_kg"),
    training_habits: text(form, "training_habits"),
    recent_workout: text(form, "recent_workout"),
    default_rest_seconds: number(form, "default_rest_seconds"),
    default_equipment: list(form, "default_equipment"),
    fitness_levels: fitnessLevels(form),
    preferences: list(form, "preferences"),
    sensitive_constraints: sensitiveConstraints(form),
  };
}

export async function submitProfile(
  _prevState: ProfileFormState,
  form: FormData,
): Promise<ProfileFormState> {
  const result = await saveProfile(toProfileInput(form));
  if (!result.success) {
    return { error: result.error ?? "Could not save your profile." };
  }
  redirect("/dashboard");
}
import Link from "next/link";

import { RedeemShareButton } from "@/components/RedeemShareButton";
import { previewShare } from "@/lib/sessions";
import { toSharePreviewView } from "@/lib/redeem-share";
import { PageHeader } from "@/components/pulse/page-header";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { buttonVariants } from "@/components/ui/button";

// The recipient's Share Link landing page (Redeem, ADR-0057, issue #398). Previews the linked
// Session — its Name, Training Type, and Author — without redeeming (the preview leaks nothing
// beyond those), then offers to Redeem it into an independent copy the recipient owns. A revoked or
// unknown link renders a plain "no longer available" state rather than any Session detail.
export default async function SharedSessionPage({
  params,
}: {
  params: Promise<{ token: string }>;
}) {
  const { token } = await params;
  const preview = toSharePreviewView(await previewShare(token));

  if (!preview.valid) {
    return (
      <section className="flex flex-col gap-7">
        <PageHeader overline="PULSE // SHARED SESSION" title="Link unavailable" />
        <Card className="flex flex-col gap-4 p-5">
          <p className="font-sans text-[14px] leading-relaxed text-text-secondary">
            This share link is no longer available. It may have been revoked by the
            person who shared it, or the link may be incorrect.
          </p>
          <Link
            href="/train"
            className={buttonVariants({ variant: "secondary", className: "w-full" })}
          >
            Back to Train
          </Link>
        </Card>
      </section>
    );
  }

  return (
    <section className="flex flex-col gap-7">
      <PageHeader
        overline="PULSE // SHARED SESSION"
        title={preview.displayName}
        action={
          <Badge variant="magenta" className="capitalize">
            {preview.trainingType}
          </Badge>
        }
      />

      {/* Author credit (CONTEXT: Author): the human who first created this plan — preserved on the
          copy when redeemed, so even a shared plan keeps crediting its original creator. */}
      <p className="-mt-4 font-sans text-[13px] text-text-secondary">
        {preview.authorByline}
      </p>

      <Card className="flex flex-col gap-4 p-5">
        <p className="font-sans text-[14px] leading-relaxed text-text-secondary">
          Save this session to get your own independent copy. You can rename, edit,
          log, and re-share it — changes never affect the original.
        </p>
        <RedeemShareButton token={token} />
      </Card>
    </section>
  );
}
