import { AlertTriangle, CheckCircle2, Info } from "lucide-react";

import { cn } from "@/lib/utils";

type Tone = "error" | "success" | "info";

interface AlertProps extends React.HTMLAttributes<HTMLDivElement> {
  tone?: Tone;
}

const TONE: Record<Tone, { wrap: string; icon: React.ElementType }> = {
  error: { wrap: "border-magenta/40 bg-magenta-dim text-magenta", icon: AlertTriangle },
  success: { wrap: "border-cyan/40 bg-cyan-dim text-cyan", icon: CheckCircle2 },
  info: { wrap: "border-border bg-surface text-text-secondary", icon: Info },
};

// Inline status message used for form errors ("role=alert"), save confirmations,
// and load failures — themed to the pulse accent palette.
export function Alert({
  tone = "info",
  className,
  children,
  ...props
}: AlertProps): React.JSX.Element {
  const { wrap, icon: Icon } = TONE[tone];
  return (
    <div
      className={cn(
        "flex items-start gap-2.5 rounded-sm border px-3.5 py-3 text-sm",
        wrap,
        className,
      )}
      {...props}
    >
      <Icon className="mt-0.5 h-4 w-4 shrink-0" aria-hidden />
      <div className="font-mono text-[13px] leading-relaxed">{children}</div>
    </div>
  );
}
import * as React from "react";

import { cn } from "@/lib/utils";

type Accent = "cyan" | "violet" | "magenta" | "blue";

interface SegmentedBarProps {
  // Completion 0–1; rounds to the nearest of `segments` filled cells.
  value: number;
  segments?: number;
  accent?: Accent;
  className?: string;
}

const ACCENT_BG: Record<Accent, string> = {
  cyan: "bg-cyan",
  violet: "bg-violet",
  magenta: "bg-magenta",
  blue: "bg-blue",
};

// The segmented progress meter from pulse.pen queued-protocol rows: a fixed
// number of rounded cells, filled cells in the accent color and the rest in the
// elevated surface. A clearer, more "instrument" read than a smooth bar.
export function SegmentedBar({
  value,
  segments = 10,
  accent = "cyan",
  className,
}: SegmentedBarProps): React.JSX.Element {
  const clamped = Math.max(0, Math.min(1, value));
  const filled = Math.round(clamped * segments);

  return (
    <div
      className={cn("flex gap-[3px]", className)}
      role="progressbar"
      aria-valuenow={Math.round(clamped * 100)}
      aria-valuemin={0}
      aria-valuemax={100}
    >
      {Array.from({ length: segments }, (_, index) => (
        <span
          key={index}
          className={cn(
            "h-1 flex-1 rounded-[1px]",
            index < filled ? ACCENT_BG[accent] : "bg-elevated",
          )}
        />
      ))}
    </div>
  );
}
